import { ReactNode, useEffect, useState } from 'react'
import { envVariables } from '../../config/env'
import { axiosInterceptableInstance } from '../../config/http_client'
import useAuth from '../auth/use'
import NotificationContext from './context'
import {
  Banner as BannerInterface,
  Notification as NotificationInterface,
  NotificationState,
} from './state'
import {
  BANNER_NOTIFICATION_CACHE_TIME,
  NOTIFICATION_CACHE_TIME,
  getTimeWithNow,
} from 'shared/cache'
import { getItemFromCache, setItemFromCache } from 'utils/cacheUtils'
import { CacheDataLastTime } from 'domain/model/background'
import { isDateExpired } from 'utils/dateHelper'
import {
  BANNERS_LOCAL_STORAGE_NAME,
  NOTIFICATION_LOCAL_STORAGE_NAME,
} from 'shared/notification'

interface NotificationProviderProps {
  children: ReactNode
}
const NotificationProvider = ({ children }: NotificationProviderProps) => {
  const { isAuthenticated, token } = useAuth()

  const [notificationsState, setNotificationsState] =
    useState<NotificationInterface[]>()

  const [bannersState, setBannersState] = useState<BannerInterface[]>()

  useEffect(() => {
    getNotifications()
    getBanners()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token])

  const getNotifications = async () => {
    if (!isAuthenticated) {
      return
    }

    const notificationsCache =
      (await getItemFromCache<CacheDataLastTime<NotificationInterface[]>>(
        NOTIFICATION_LOCAL_STORAGE_NAME
      )) || null

    if (notificationsCache && !isDateExpired(notificationsCache.lastFetch))
      return setNotificationsState(notificationsCache.data)

    await axiosInterceptableInstance({
      method: envVariables.api.notifications.get.method,
      url: envVariables.api.notifications.get.path,
      headers: {
        Authorization: `Bearer ${token?.access_token}`,
      },
    })
      .then(async ({ data }) => {
        setNotificationsState(data.data)

        const cacheData: CacheDataLastTime<NotificationInterface[]> = {
          data: { ...data.data },
          lastFetch: getTimeWithNow(NOTIFICATION_CACHE_TIME),
        }

        await setItemFromCache(
          NOTIFICATION_LOCAL_STORAGE_NAME,
          JSON.stringify(cacheData)
        )
      })
      .catch((_) => {})
  }

  const getBanners = async () => {
    if (!isAuthenticated) {
      return
    }

    const bannerCache =
      (await getItemFromCache<CacheDataLastTime<BannerInterface[]>>(
        BANNERS_LOCAL_STORAGE_NAME
      )) || null

    if (bannerCache && !isDateExpired(bannerCache.lastFetch))
      return setBannersState(bannerCache.data)

    await axiosInterceptableInstance({
      method: envVariables.api.notifications.get.method,
      url: '/banners',
      headers: {
        Authorization: `Bearer ${token?.access_token}`,
      },
    })
      .then(async ({ data }) => {
        setBannersState(data)

        const cacheData: CacheDataLastTime<BannerInterface[]> = {
          data: data ?? [],
          lastFetch: getTimeWithNow(BANNER_NOTIFICATION_CACHE_TIME),
        }

        await setItemFromCache(
          BANNERS_LOCAL_STORAGE_NAME,
          JSON.stringify(cacheData)
        )
      })
      .catch((_) => {})
  }

  const state: NotificationState = {
    banners: bannersState || [],
    notifications: notificationsState || [],
    fetchNotifications: getNotifications,
  }

  return (
    <NotificationContext.Provider value={state}>
      {children}
    </NotificationContext.Provider>
  )
}

export default NotificationProvider
