type SetParamValueParams = {
  prefix: string;
  value: string;
};
export class UrlService {
  private url: string;

  private queries: URLSearchParams;

  constructor(completeUrl: string) {
    const [url, queries] = completeUrl.split('?');
    this.url = url;
    this.queries = new URLSearchParams(queries);
  }

  setParamValue({ prefix, value }: SetParamValueParams) {
    this.queries.set(prefix, value);
  }

  getUrl() {
    const queries: string[] = [];

    this.queries.forEach((value, key) => {
      queries.push(`${key}=${value}`);
    });
    return `${this.url}?${queries.join('&')}`;
  }
}
