import InsertDriveFileOutlinedIcon from '@mui/icons-material/InsertDriveFileOutlined'
import LogoutIcon from '@mui/icons-material/Logout'
import StarBorderOutlinedIcon from '@mui/icons-material/StarBorderOutlined'
import { SvgIcon } from '@mui/material'
import {
  FooterEventIds,
  eventPreferencesFooterAdapter,
  footerEventLinks,
} from 'adapter/event-adapter/preferences/footer-adapter'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import { useCompanyDiscounts } from 'hooks/company-discounts'
import { useCallback } from 'react'
import { useTheme } from 'styled-components'
import { getCurrentUrl } from 'utils/location/get-current-url'
import * as S from './styles'

const makeAction = (url: string) => () => window.open(url, '_blank')

function PreferencesFooter() {
  const { companyDiscounts } = useCompanyDiscounts()
  const theme = useTheme()
  const { logout } = useAuth()

  const preferencesFooterList = [
    {
      id: 'avalie-nossa-extensao',
      text: 'Avalie nossa extensão',
      color: theme.colors.pickles,
      icon: (
        <SvgIcon sx={{ fontSize: '16px' }} htmlColor={theme.colors.pickles}>
          <StarBorderOutlinedIcon />
        </SvgIcon>
      ),
      action: makeAction(footerEventLinks.rate),
    },
    {
      id: 'termos-de-uso',
      text: 'Termos de uso',
      color: theme.colors.bowl,
      icon: (
        <SvgIcon sx={{ fontSize: '16px' }} htmlColor={theme.colors.bowl}>
          <InsertDriveFileOutlinedIcon />
        </SvgIcon>
      ),
      action: makeAction(footerEventLinks.terms_of_use),
    },
    {
      id: 'sair-da-extensao',
      text: 'Sair da extensão',
      color: theme.colors.steel,
      icon: (
        <SvgIcon sx={{ fontSize: '16px' }} htmlColor={theme.colors.steel}>
          <LogoutIcon />
        </SvgIcon>
      ),
      action: logout,
    },
  ]

  const eventTrigger = useCallback(
    async (id: keyof typeof FooterEventIds) => {
      const active_url = await getCurrentUrl(EventOrigin.EXTENSION)

      eventPreferencesFooterAdapter({
        id,
        eventProps: {
          active_url,
          shortname: companyDiscounts?.company_info.short_name ?? '',
          company_name: companyDiscounts?.company_info.name ?? '',
          reputation:
            companyDiscounts?.company_info.general_reputation?.status ?? '',
          score:
            companyDiscounts?.company_info.general_reputation?.average_score ??
            '',
          ra_verificada:
            companyDiscounts?.company_info.company_flags.is_verified ?? false,
          component: ComponentLocation.MODAL_EXTENSION,
          area: AreaLocation.PREFERENCES,
        },
      })
    },
    [
      companyDiscounts?.company_info.general_reputation?.average_score,
      companyDiscounts?.company_info.general_reputation?.status,
      companyDiscounts?.company_info.company_flags.is_verified,
      companyDiscounts?.company_info.name,
      companyDiscounts?.company_info.short_name,
    ]
  )

  return (
    <S.Main>
      {preferencesFooterList.map(({ id, text, color, icon, action }) => (
        <S.Option id={id}>
          <S.Item
            color={color}
            onClick={async () => {
              await eventTrigger(id as keyof typeof FooterEventIds)
              await action()
            }}
          >
            {icon} {text}
          </S.Item>
        </S.Option>
      ))}
    </S.Main>
  )
}

export default PreferencesFooter
