type QueryObject = {
  [key: string]: string | number | Date;
};

export const makeQuery = (querysObject: QueryObject) => {
  let query = '';
  const keys = Object.keys(querysObject);

  keys.forEach(key => {
    if (querysObject[key]) {
      if (!query) {
        return (query += `?${key}=${querysObject[key]}`);
      }
      query += `&${key}=${querysObject[key]}`;
    }
  });

  return query;
};
