import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import Container from 'components/Container'
import Discounts from 'components/Discounts'
import HasDiscounts from 'components/HasDiscounts'
import NoHasDiscounts from 'components/NoHasDiscounts'
import Reputation from 'components/Reputation'
import CommonSurvey from 'components/Survey'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { Survey } from 'domain/model/survey'
import { getSurvey } from 'domain/services/survey'
import {
  getChromeLocalData,
  setChromeLocalData,
} from 'hooks/chrome-storage-change-data'
import { useCompanyDiscounts } from 'hooks/company-discounts'
import { useProfile } from 'hooks/Profile/use'
import React, { useEffect, useMemo, useState } from 'react'
import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { isEmpty } from 'utils/isEmpty'
import { getCurrentUrl } from 'utils/location/get-current-url'
import * as C from './components'
import * as S from './styles'

export type StoreStatus =
  | 'RA1000'
  | 'GREAT'
  | 'GOOD'
  | 'REGULAR'
  | 'BAD'
  | 'NOT_RECOMMENDED'
  | 'UNDER_REVIEW'
  | 'NO_INDEX'
  | 'NO_INDEX_VERIFIED'

const Home: React.FC = () => {
  const {
    loading,
    companyDiscounts,
    couponsQuantity,
    offersQuantity,
    couponsAndOffersQuantity,
  } = useCompanyDiscounts()
  const [survey, setSurvey] = useState<Survey>()
  const { cachedProfile } = useProfile()

  const handleSurvey = async () => {
    try {
      const data = await getSurvey()
      setSurvey(data)
    } catch (_) {
      setSurvey(undefined)
    }
  }

  useEffect(() => {
    handleSurvey()
  }, [])

  useEffect(() => {
    async function openModalEvent() {
      const popupOpened = await getChromeLocalData('popup_opened')
      const popupOpenedEventTriggered = await getChromeLocalData(
        'popup_opened_event_triggered'
      )

      if (
        popupOpened?.popup_opened &&
        !popupOpenedEventTriggered?.popup_opened_event_triggered
      ) {
        await setChromeLocalData({ popup_opened_event_triggered: true })
        try {
          const active_url = await getCurrentUrl(EventOrigin.EXTENSION)

          eventAdapter({
            target: EventAdapterTarget.current,
            data: {
              event: `${eventNamePrefix}open_modal`,
              eventProps: {
                active_url,
                shortname: companyDiscounts?.company_info?.short_name ?? '',
                company_name: companyDiscounts?.company_info?.name ?? '',
                reputation:
                  companyDiscounts?.company_info?.general_reputation?.status ??
                  '',
                score:
                  companyDiscounts?.company_info?.general_reputation
                    ?.average_score ?? '',
                ra_verificada:
                  companyDiscounts?.company_info?.company_flags.is_verified ??
                  false,
                total_discounts: couponsAndOffersQuantity,
                coupons: couponsQuantity ?? 0,
                offers: offersQuantity ?? 0,
                component: ComponentLocation.EXTENSION,
                area: AreaLocation.EXTENSION_ICON,
              },
            },
          })
        } catch (e) {
          await setChromeLocalData({ popup_opened_event_triggered: false })
          console.error('Open extension modal: ', e)
        }
      }
    }
    openModalEvent()
  }, [
    companyDiscounts,
    couponsAndOffersQuantity,
    couponsQuantity,
    offersQuantity,
  ])

  const eventObject = {
    eventOrigin: EventOrigin.EXTENSION,
    componentLocation: ComponentLocation.MODAL_EXTENSION,
    areaLocation: AreaLocation.HOME,
  }

  const canShowStoreComponents = useMemo(
    () =>
      companyDiscounts?.company_info &&
      !isEmpty(companyDiscounts?.company_info),
    [companyDiscounts?.company_info]
  )

  return (
    <Container>
      {loading ? (
        <>
          <Skeleton width={266} height={105} />
          <Skeleton width={266} height={48} />
        </>
      ) : canShowStoreComponents ? (
        <Reputation
          eventObject={eventObject}
          companyInfo={companyDiscounts!.company_info}
        />
      ) : (
        <C.NotFoundStore />
      )}
      <S.Padding>
        {!!survey && survey.active && (
          <CommonSurvey
            data={survey}
            userId={cachedProfile?.profile?.user.id}
          />
        )}
        {loading ? (
          <Skeleton width={266} height={400} />
        ) : (
          <Discounts
            eventObject={eventObject}
            HasDiscounts={HasDiscounts}
            NoHasDiscounts={NoHasDiscounts}
          />
        )}
      </S.Padding>
    </Container>
  )
}

export default Home
