import { mdiMessageText } from '@mdi/js'
import Icon from '@mdi/react'
import { Survey as SurveyData } from 'domain/model/survey'
import { light } from '../../styles/themes/basic'
import * as S from './styles'
import { useProfile } from 'hooks/Profile/use'

interface ISurvey {
  data: SurveyData
  userId?: string
}
const Survey = ({ data, userId }: ISurvey) => {

  const handleLink = () => {
    return  userId ? `${data?.link}?${data?.user_id_param_name}=${userId}` : data?.link
  }
  return (
    <S.Main data-test-id='survey'>
      <S.Text data-test-id='description'>{data.description}</S.Text>
      <S.Link
        href={handleLink()}
        target='_blank'
        rel='noreferrer'
        data-test-id='link'
      >
        <Icon
          path={mdiMessageText}
          size='16px'
          color={light.colors.secundary}
        />
        <p data-test-id='link-text'>Avaliar</p>
      </S.Link>
    </S.Main>
  )
}

export default Survey
