import { googleAnalyticsTrack } from './google-analytics-track'
import { mixpanelTrack } from './mixpanel-track'

export const EventAdapterTargetList = {
  mixpanel: 'mixpanel',
  googleAnalytics: 'googleAnalytics',
}

export enum EventAdapterTarget {
  current = 'googleAnalytics',
}

export interface EventAdapterData {
  event: string
  eventProps?: any
}

export interface EventAdapterProps {
  target: keyof typeof EventAdapterTargetList
  data: EventAdapterData
}
export function eventAdapter({ target, data }: EventAdapterProps) {
  if (target === EventAdapterTargetList.mixpanel) return mixpanelTrack(data)
  if (target === EventAdapterTargetList.googleAnalytics)
    return googleAnalyticsTrack(data)
}
