import { mdiChevronDown, mdiChevronUp } from '@mdi/js'
import Icon from '@mdi/react'
import Text from 'components/Text'
import { light } from 'styles/themes/basic'
import { Phrase } from 'utils/getPhrases'
import * as S from './styles'

const statusToHiddenScore = [
  'Não recomendado',
  'Sem reputação definida',
  'Reputação suspensa',
]

interface IReputationScore {
  reputation: Phrase
  average_score?: string
  expanded?: boolean
}
const ReputationScore = ({
  reputation,
  average_score,
  expanded,
}: IReputationScore) => {
  const handleShowFraction = () => {
    return !statusToHiddenScore.includes(reputation.name)
  }

  return (
    <S.Main>
      <S.Header>
        <img
          src={reputation!.image}
          alt='reputation'
          width='32px'
          height='32px'
        />
        <S.DivReputation>
          <Text color='steel' size='14px' fontWeight='600' margin='0'>
            {reputation!.name}
          </Text>
        </S.DivReputation>
      </S.Header>
      {handleShowFraction() && (
        <>
          <S.Divider />
          <S.ScoreContainer>
            {average_score && (
              <Text color='steel' size='16px' fontWeight='bold' margin='0'>
                {average_score}
              </Text>
            )}
            <Text color='steel' size='9px' margin='0'>
              / 10
            </Text>
          </S.ScoreContainer>
        </>
      )}
      <S.Icon>
        <Icon
          path={expanded ? mdiChevronUp : mdiChevronDown}
          size='12px'
          color={light.colors.steel}
        />
      </S.Icon>
    </S.Main>
  )
}

export default ReputationScore
