import { envVariables } from 'config/env'
import { axiosInterceptableInstance } from 'config/http_client'
import { IToken } from 'hooks/auth/state'

export interface PutExtensionConfigProps {
  configId: string
  extensionId: string
  token?: IToken
  newConfigStatus: boolean
}
export async function putExtensionConfig({
  configId,
  extensionId,
  token,
  newConfigStatus,
}: PutExtensionConfigProps): Promise<any> {
  try {
    if (!token) throw new Error('Invalid token.')

    return await axiosInterceptableInstance({
      method: envVariables.api.account.configs.method,
      url: envVariables.api.account.configs.path + configId,
      headers: {
        Authorization: `Bearer ${token.access_token}`,
      },
      data: {
        isChecked: newConfigStatus,
        extension_id: extensionId,
      },
    })
  } catch (e: any) {
    console.error(`PUT EXTENSION CONFIG: ${e}`)
    const {
      response: { data, status },
    } = e
    return {
      status,
      message: data?.message
        ? data?.message
        : 'Ocorreu um erro inexperado! Tente novamente mais tarde.',
    }
  }
}
