import { putExtensionConfig } from 'domain/services/profile/put-extension-config'
import { useAlert } from 'hooks/AlertProvider/use'
import useAuth from 'hooks/auth/use'
import { useProfile } from 'hooks/Profile/use'
import { ExtensionConfig } from 'pages/User/interface'

export function useUpdateConfig() {
  const { token } = useAuth()
  const { openAlert } = useAlert()
  const { cachedProfile, setProfile } = useProfile()

  const handleUpdateConfig = async (config: ExtensionConfig) => {
    if (cachedProfile?.profile) {
      const newConfigStatus = !config.isChecked

      const currentProfileConfigs = cachedProfile?.profile?.extension_config
        ? [...cachedProfile.profile.extension_config]
        : []

      const foundConfig = currentProfileConfigs.find(
        (currConfig) => currConfig.id === config.id
      )

      if (foundConfig) foundConfig.isChecked = newConfigStatus

      await putExtensionConfig({
        configId: config.id,
        extensionId: config.extension_id,
        newConfigStatus,
        token,
      }).then((data) => {
        if (data.status < 200 || data.status > 299)
          return openAlert?.({
            title: 'Erro',
            message: data.message,
            severity: 'error',
          })

        openAlert?.({
          title: 'Sucesso',
          message: newConfigStatus
            ? 'Informação salva com sucesso!'
            : 'Desabilitado com sucesso!',
          severity: 'success',
        })
        setProfile?.({
          ...cachedProfile,
          profile: {
            ...cachedProfile.profile,
            extension_config: currentProfileConfigs,
          },
        })
      })
    }
  }

  return { handleUpdateConfig }
}
