import CheckCircleIcon from '@mui/icons-material/CheckCircle'
import CloseIcon from '@mui/icons-material/Close'
import ErrorIcon from '@mui/icons-material/Error'
import { useEffect, useRef } from 'react'
import * as S from './styles'

export type Severity = 'success' | 'warning' | 'error'
export interface AlertProps {
  title: string
  message: string
  severity: Severity
  onClose: () => void
}
export function Alert({
  message,
  severity = 'success',
  onClose,
  title,
}: AlertProps) {
  const mainRef = useRef<HTMLBaseElement>(null)

  useEffect(() => {
    const currentElement = mainRef?.current
    const removeElement = () => onClose()
    if (currentElement) {
      currentElement?.addEventListener('animationend', removeElement, false)
    }

    return () => {
      if (currentElement) {
        currentElement?.removeEventListener(
          'animationend',
          removeElement,
          false
        )
      }
    }
  }, [message, onClose])

  return (
    <S.Main severity={severity} ref={mainRef}>
      <S.AlertBar severity={severity}>
        <S.IconBorder severity={severity}>
          {severity === 'error' ? <ErrorIcon /> : <CheckCircleIcon />}
        </S.IconBorder>
        <S.TextBox severity={severity}>
          <h2>{title}</h2>
          <p>{message}</p>
        </S.TextBox>
        <S.CloseButton onClick={onClose}>
          <CloseIcon />
        </S.CloseButton>
      </S.AlertBar>
    </S.Main>
  )
}
