import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { useDiscountsSummary } from 'hooks/DiscountsSummaryProvider/use'
import { useSelectedCompanyDiscounts } from 'hooks/selected-company-discounts'
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import 'react-loading-skeleton/dist/skeleton.css'
import { SearchProps } from 'shared/types/search-page'
import Container from '../../components/Container'
import HasDiscounts from '../../components/HasDiscounts'
import NoCoupons from './components/NoCoupons'

const Search = ({ minHeight = '480px' }: SearchProps) => {
  const {
    loading,
    companyDiscounts,
    couponsQuantity,
    couponsAndOffersQuantity,
    hasCoupons,
    hasOffers,
    clearSelectedCompanyDiscounts,
  } = useSelectedCompanyDiscounts()
  const [discountsSummary, setDiscountsSummary] = useState<
    DiscountsSummaryApiResponse[]
  >([])
  const ref = useRef<null | HTMLDivElement>(null)

  const {
    discountsSummary: discountsSummaryHook,
    loading: loadingDiscountsSummary,
  } = useDiscountsSummary()

  useEffect(() => {
    if (discountsSummaryHook && !loadingDiscountsSummary)
      setDiscountsSummary(discountsSummaryHook)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    if (couponsQuantity) {
      ref.current?.scrollIntoView({ behavior: 'smooth' })
    }
  }, [couponsQuantity])

  const handleBack = () => {
    clearSelectedCompanyDiscounts?.()
  }

  const hasCouponOrOffers = useMemo(
    () => hasCoupons?.() || hasOffers?.(),
    [hasCoupons, hasOffers]
  )

  const handleSearch = useCallback(
    (term: string) => {
      if (discountsSummaryHook) {
        const filteredDiscounts = discountsSummaryHook.filter((discount) =>
          discount.company_info.name.toLowerCase().includes(term.toLowerCase())
        )
        setDiscountsSummary(filteredDiscounts)
      }
    },
    [discountsSummaryHook]
  )

  return (
    <Container minHeight={minHeight} padding='16px 12px'>
      {hasCouponOrOffers && companyDiscounts ? (
        <HasDiscounts
          companyDiscounts={companyDiscounts}
          couponsAndOffersQuantity={couponsAndOffersQuantity}
          couponsQuantity={couponsQuantity}
          eventObject={{
            eventOrigin: EventOrigin.EXTENSION,
            componentLocation: ComponentLocation.MODAL_EXTENSION,
            areaLocation: AreaLocation.SEARCH,
          }}
          handleBack={handleBack}
          hasSelectedStore={true}
        />
      ) : (
        <NoCoupons
          searchHandle={handleSearch}
          loading={loadingDiscountsSummary || loading}
          filteredDiscountsSummary={discountsSummary}
        />
      )}
    </Container>
  )
}

export default Search
