import { b64EncodeUnicode } from './base64'
import { makeQuery } from './makeQuery'
import { IComparatorSellerReputation } from './openRamaisRedirectPage'

const protocols = ['https://', 'http://']

export const urlContainsProtocol = (url: string) =>
  protocols.some((protocol) => url.includes(protocol))

export const makeStoreUrl = (url: string) => {
  if (urlContainsProtocol(url)) {
    return url
  }

  return `https://${url}`
}

interface IOpenRedirectPage {
  url: string
  code?: string
  seller: string
  sellerReputation: IComparatorSellerReputation
  sellerLogoUrl?: string
}

export const makeRedirectUrl = ({
  url,
  code = '',
  seller,
  sellerReputation,
  sellerLogoUrl,
}: IOpenRedirectPage) => {
  const query = makeQuery({
    code,
    seller,
    sellerLogoUrl: sellerLogoUrl || '',
    sellerReputation: JSON.stringify(sellerReputation),
  })
  return `/redirect/?redirectUrl=${b64EncodeUnicode(
    url
  )}&sellerData=${b64EncodeUnicode(query)}`
}
