import { handleRequest } from 'utils/handleRequest'
import { Survey } from '../model/survey'

export const getSurvey: () => Promise<Survey | undefined> = async () => {
  try {
    return await handleRequest<Survey | undefined>({
      url: '/survey',
      statusToReject: [204],
    })
  } catch (e: any) {
    console.error('GET Survey: ', e.message)
    return undefined
  }
}
