import { EventOrigin } from 'domain/model/event'

export async function getCurrentUrl(origin: EventOrigin) {
  let active_url = ''

  try {
    if (origin === EventOrigin.EXTENSION) {
      const tabs = await chrome.tabs.query({
        active: true,
        currentWindow: true,
      })

      active_url = tabs[0]?.url ?? ''
    } else {
      active_url = window.location.href
    }
  } catch (e) {
    console.error('Get current url: ', e)
    active_url = ''
  }

  return active_url
}
