import { StorageArea } from 'domain/model/chrome-storage'
import { useEffect, useState } from 'react'

export const useChromeStorageListener = <T,>(
  storageName: string,
  storageArea: StorageArea
) => {
  interface ListenerDataProps {
    newValue: T | undefined
    oldValue: T | undefined
  }
  const [listenerData, setListenerData] = useState<ListenerDataProps>()
  const [currentData, setCurrentData] = useState<T>()

  useEffect(() => {
    chrome.storage.onChanged.addListener((response) => {
      if (!response?.[storageName]) return

      setListenerData({
        newValue: response?.[storageName].newValue,
        oldValue: response?.[storageName].oldValue,
      })
      return setCurrentData(response?.[storageName].newValue)
    })

    chrome.storage[storageArea]
      .get(storageName)
      .then((response) => {
        setCurrentData(response[storageName])
      })
      .catch((e) => {
        console.error('Chrome storage local get error: ', e)
      })
  }, [storageName, storageArea])

  return { listenerData, currentData }
}

export const useChromeStorageLocal = <T,>(storageName: string) => {
  return useChromeStorageListener<T>(storageName, 'local')
}

export const useChromeStorageSync = <T,>(storageName: string) => {
  return useChromeStorageListener<T>(storageName, 'sync')
}
