import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import { EventObject } from 'domain/model/event'
import { useCallback } from 'react'
import { Banner } from 'scripts/pin-component/hooks/notifications/state'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import * as S from './styles'

interface MarketingBannerProps extends Banner {
  companyInfo?: DiscountsCompanyInfo | null
  eventObject: EventObject
}

const MarketingBanner = ({
  id,
  image,
  companyInfo,
  button_action,
  button_text,
  description,
  eventObject,
}: MarketingBannerProps) => {
  const eventTrigger = useCallback(async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}banner`,
        eventProps: {
          active_url,
          shortname: companyInfo?.short_name ?? '',
          company_name: companyInfo?.name ?? '',
          reputation: companyInfo?.general_reputation?.status ?? '',
          score: companyInfo?.general_reputation?.average_score ?? '',
          ra_verificada: companyInfo?.company_flags.is_verified ?? false,
          component: eventObject.componentLocation,
          area: eventObject.areaLocation,
          description_banner: description,
          link_banner: button_action,
        },
      },
    })
  }, [
    button_action,
    description,
    eventObject,
    companyInfo?.general_reputation?.average_score,
    companyInfo?.general_reputation?.status,
    companyInfo?.company_flags.is_verified,
    companyInfo?.name,
    companyInfo?.short_name,
  ])

  return (
    <S.Main id={id}>
      <S.Image src={image} />
      <S.Rigth>
        <S.Title>{description}</S.Title>
        <S.Button
          target='_blank'
          href={button_action}
          rel='noreferrer'
          onClick={eventTrigger}
        >
          {button_text}
        </S.Button>
      </S.Rigth>
    </S.Main>
  )
}

export default MarketingBanner
