import * as S from './styles'

interface ListProps {
  text: string
  value: any
}
interface ButtonOptionProps {
  title: string
  list: ListProps[]
  buttonId: string
  currentValue: any
  handleChange: (newValue: any) => void
}
function ButtonOption({
  title,
  list,
  buttonId,
  currentValue,
  handleChange,
}: ButtonOptionProps) {
  return (
    <S.Main>
      <S.Title>{title}</S.Title>

      <S.SilenceList>
        {list.map(({ text, value }, index) => (
          <li key={`${index}-${value}`}>
            <S.SilenceItem
              id={`${buttonId}_${value}_minutos`}
              selected={value === currentValue}
              disabled={value === currentValue}
              onClick={() => {
                handleChange(value)
              }}
            >
              {text}
            </S.SilenceItem>
          </li>
        ))}
      </S.SilenceList>
    </S.Main>
  )
}

export default ButtonOption
