import { ReactNode } from 'react'

interface Props {
  components: Array<({ children }: { children: ReactNode }) => JSX.Element>
  children: ReactNode
}

export function Compose({ components = [], children }: Props) {
  return (
    <>
      {components.reduceRight(
        (acc, Component) => (
          <Component>{acc}</Component>
        ),
        children
      )}
    </>
  )
}
