import styled, { DefaultTheme, keyframes } from 'styled-components'

export const Container = styled.div`
  width: 100%;
  height: 277px;
  padding: 8px;

  > div:last-child {
    margin-top: 16px;
  }
`

const opacityAnimation = (theme: DefaultTheme) => keyframes`
  0% { background-color: ${theme.colors.iron}; }
  50% { background-color: ${theme.colors.gray}; }
  100% { background-color: ${theme.colors.iron}; }
`

interface ISkeleton {
  width: string;
  height: string;
}
export const Skeleton = styled.div<ISkeleton>`
  background-color: ${({ theme }) => theme.colors.iron};
  width: ${({ width }) => width};
  height: ${({ height }) => height};

  animation-name: ${({ theme }) => opacityAnimation(theme)};
  animation-duration: 1s;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
`