import { mdiAccountOutline } from '@mdi/js'
import Icon from '@mdi/react'
import { useProfile } from 'hooks/Profile/use'
import useAuth from 'hooks/auth/use'
import { useNavigate } from 'react-router'
import * as S from './styles'
import Loading from 'components/Loading'

interface LoginButtonProps {
  eventTrigger: () => void
}
const LoginButton = ({ eventTrigger }: LoginButtonProps) => {
  const { isAuthenticated, loading } = useAuth()
  const { cachedProfile } = useProfile()
  const navigate = useNavigate()

  const loginHandle = () => {
    if (!isAuthenticated) eventTrigger()

    navigate('/users')
  }

  const handleText = () => {
    if (loading) {
      return (
        <>
          Entrar
          <Loading />
        </>
      )
    }

    if (isAuthenticated) {
      return cachedProfile?.profile?.user?.name || ''
    }

    return 'Entrar'
  }

  return (
    <S.Main
      isAuthenticated={isAuthenticated}
      loading={loading}
      onClick={loginHandle}
    >
      {!loading && (
        <S.IconMain>
          <Icon path={mdiAccountOutline} />
        </S.IconMain>
      )}
      <S.TextButton loading={loading} isAuthenticated={isAuthenticated}>
        {handleText()}
      </S.TextButton>
    </S.Main>
  )
}

export default LoginButton
