import { ReactNode, useState } from 'react'
import { SelectedCompanyContext } from './context'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'

interface SelectedCompanyProviderProps {
  children: ReactNode
}
const SelectedCompanyProvider = ({
  children,
}: SelectedCompanyProviderProps) => {
  const [selectedCompany, setSelectedCompany] =
    useState<DiscountsSummaryApiResponse>()

  const selectCompany = (discount: DiscountsSummaryApiResponse) => {
    setSelectedCompany({ ...discount })
  }

  const clearSelectedCompany = () => {
    setSelectedCompany(undefined)
  }

  return (
    <SelectedCompanyContext.Provider
      value={{
        selectedCompany,
        clearSelectedCompany,
        selectCompany,
      }}
    >
      {children}
    </SelectedCompanyContext.Provider>
  )
}

export default SelectedCompanyProvider
