import CloseIcon from '@mui/icons-material/Close'
import { Tooltip } from '@mui/material'
import { useCallback, useState } from 'react'
import { Dialog } from '../../Dialog'
import { preferentialEmailActions } from '../../Preferences/Main/helper'
import * as S from './styles'

interface StringOptionProps {
  title: string
  value: string
  hasPreferentialEmail: boolean
  validation?: (value: string) => boolean
  handleChange: (value: string) => void
}
function StringOption({
  title,
  value,
  hasPreferentialEmail,
  validation,
  handleChange,
}: StringOptionProps) {
  const [openAddValue, setOpenAddValue] = useState(false)

  const [inputValue, setInputValue] = useState('')
  const [canSave, setCanSave] = useState(false)

  const dialogClose = useCallback(() => {
    openAddValue && setOpenAddValue(false)
    setInputValue('')
    setCanSave(false)
  }, [openAddValue])

  const addValue = useCallback(() => {
    dialogClose()
    handleChange(inputValue)
  }, [dialogClose, handleChange, inputValue])

  const clearValue = useCallback(() => {
    handleChange('')
  }, [handleChange])

  return (
    <S.Main>
      <S.Header>
        <S.Title>{title}</S.Title>

        <S.Actions>
          {preferentialEmailActions.map(({ id, icon, tooltip, type }) => (
            <li key={id}>
              <Tooltip title={tooltip}>
                <S.ActionButton
                  id={id}
                  onClick={() => {
                    type === 'add' && setOpenAddValue(true)
                  }}
                >
                  {icon}
                </S.ActionButton>
              </Tooltip>
            </li>
          ))}
        </S.Actions>
      </S.Header>

      <S.Content>
        <S.ContentText>{value}</S.ContentText>
        {hasPreferentialEmail ? (
          <S.ContextButton onClick={clearValue}>
            <CloseIcon
              sx={{
                color: '#4B5963',
                width: 'fit-content',
                height: 'fit-content',
              }}
            />
          </S.ContextButton>
        ) : null}
      </S.Content>

      <Dialog
        canSave={canSave}
        openAdd={openAddValue}
        dialogTitle='Adicione o seu melhor emails para receber comunicações de descontos e ofertas'
        addValue={addValue}
        dialogClose={dialogClose}
        setInputValue={setInputValue}
        setCanSave={setCanSave}
        inputValue={inputValue}
        inputLabel='Adicionar email'
        inputValueIsValid={(value) => validation?.(value) ?? true}
      />
    </S.Main>
  )
}

export default StringOption
