import { FlagsProvider } from 'flagged'
import { Provider } from 'Provider'
import { useEffect } from 'react'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { CONFIGURATIONS } from 'shared/configurations'
import { ThemeProvider } from 'styled-components'
import Footer from './components/Footer'
import Header from './components/Header'
import Search from './pages/Search'
import Home from './pages/Home'
import Notification from './pages/Notification'
import User from './pages/User'
import * as S from './styles'
import Global from './styles/global'
import { light } from './styles/themes/basic'
import { setChromeLocalData } from 'hooks/chrome-storage-change-data'

declare global {
  interface Window {
    isPopup: boolean
  }
}

function App() {
  const configs = CONFIGURATIONS

  useEffect(() => {
    async function openPopup() {
      await setChromeLocalData({ popup_opened: true })
      await setChromeLocalData({ popup_opened_event_triggered: false })
    }
    openPopup()
  }, [])

  return (
    <>
      <MemoryRouter initialEntries={['/home']}>
        <Global />
        <FlagsProvider features={configs}>
          <ThemeProvider theme={light}>
            <Provider>
              <S.Main>
                <Header />
                <S.Body>
                  <Routes>
                    <Route path='home' element={<Home />} />
                    <Route path='coupons' element={<Search />} />
                    <Route path='notifications' element={<Notification />} />
                    <Route path='users' element={<User />} />
                  </Routes>
                </S.Body>
                <Footer />
              </S.Main>
            </Provider>
          </ThemeProvider>
        </FlagsProvider>
      </MemoryRouter>
    </>
  )
}

export default App
