import { EventAdapterTargetList } from 'adapter/event-adapter'
import mixpanel from 'mixpanel-browser'

const token = process.env.REACT_APP_MIXPANEL_PROJECT_TOKEN
const debug = process.env.REACT_APP_DEV_MODE

const currentTarget: keyof typeof EventAdapterTargetList = 'googleAnalytics'
const target = EventAdapterTargetList?.googleAnalytics ?? 'googleAnalytics'

if (currentTarget === target) {
  if (!token) console.error('Invalid token!')
  else mixpanel.init(token, { debug: debug ? true : false })
}

export const mixpanelInstance = token ? mixpanel : undefined
