import { envVariables } from 'config/env'
import { axiosInterceptableInstance } from 'config/http_client'
import { IToken } from 'hooks/auth/state'

export type PinParamNames =
  | 'silence_duration_minutes'
  | 'show_only_stores_with_offers'
  | 'blocked_domain_list'
  | 'disable_pin'
export interface PutExtensionPinConfigProps {
  token?: IToken
  paramName: PinParamNames
  value: number | boolean | string | string[]
}
export async function putExtensionPinConfig({
  token,
  paramName,
  value,
}: PutExtensionPinConfigProps): Promise<any> {
  try {
    if (!token) throw new Error('Invalid token.')

    return await axiosInterceptableInstance({
      method: envVariables.api.account.pinConfigs.method,
      url: envVariables.api.account.pinConfigs.path,
      headers: {
        Authorization: `Bearer ${token.access_token}`,
      },
      data: { [paramName]: value },
    })
  } catch (e: any) {
    console.error(`PUT EXTENSION PIN CONFIG: ${e}`)
    const {
      response: { data, status },
    } = e
    return {
      status,
      message: data?.message
        ? data?.message
        : 'Ocorreu um erro inexperado! Tente novamente mais tarde.',
    }
  }
}
