import { HasDiscountsProps } from 'components/HasDiscounts'
import { NoHasDiscountsProps } from 'components/NoHasDiscounts'
import { EventObject } from 'domain/model/event'
import { useCompanyDiscounts } from 'hooks/company-discounts'
import { useMemo } from 'react'
import 'react-loading-skeleton/dist/skeleton.css'
import canShowOffersByReputation from 'utils/canShowOffersByReputation'

interface DiscountsProps {
  HasDiscounts: React.FC<HasDiscountsProps>
  NoHasDiscounts: React.FC<NoHasDiscountsProps>
  eventObject: EventObject
  hasSelectedStore?: boolean
  handleBack?: () => void
}
const Discounts = ({
  handleBack,
  eventObject,
  hasSelectedStore,
  HasDiscounts,
  NoHasDiscounts,
}: DiscountsProps) => {
  const {
    companyDiscounts,
    couponsQuantity,
    couponsAndOffersQuantity,
    isSameOrigin,
  } = useCompanyDiscounts()

  const reputationValid = useMemo(
    () =>
      canShowOffersByReputation({
        status: companyDiscounts?.company_info?.general_reputation.status,
      }),
    [companyDiscounts?.company_info?.general_reputation.status]
  )

  const couponIsValid = useMemo(
    () =>
      companyDiscounts?.discount_coupons &&
      companyDiscounts?.discount_coupons.length,
    [companyDiscounts?.discount_coupons]
  )
  const campaignIsValid = useMemo(
    () =>
      companyDiscounts?.discount_offers &&
      companyDiscounts?.discount_offers?.length,
    [companyDiscounts?.discount_offers]
  )
  const offersIsValid = useMemo(
    () => couponIsValid || campaignIsValid,
    [couponIsValid, campaignIsValid]
  )

  return (
    <>
      {offersIsValid && reputationValid && isSameOrigin ? (
        <HasDiscounts
          companyDiscounts={companyDiscounts}
          couponsQuantity={couponsQuantity}
          couponsAndOffersQuantity={couponsAndOffersQuantity}
          eventObject={eventObject}
          hasSelectedStore={hasSelectedStore}
          handleBack={handleBack}
        />
      ) : (
        <NoHasDiscounts
          reputationValid={reputationValid}
          eventObject={eventObject}
        />
      )}
    </>
  )
}

export default Discounts
