import ArrowBackIosIcon from '@mui/icons-material/ArrowBackIos'
import {
  Discount,
  DiscountsApiResponseWithPath,
} from 'domain/model/discounts/main'
import { EventObject } from 'domain/model/event'
import React, { useEffect, useMemo, useRef } from 'react'
import { light } from 'styles/themes/basic'
import CouponCard from '../CouponCard'
import OfferCard from '../OfferCard'
import { makeTitle } from './helper/makeTitle'
import * as S from './styles'

export interface HasDiscountsProps {
  companyDiscounts?: DiscountsApiResponseWithPath | null
  couponsAndOffersQuantity: number
  couponsQuantity: number
  eventObject: EventObject
  hasSelectedStore?: boolean
  handleBack?: () => void
}

const HasDiscounts: React.FC<HasDiscountsProps> = ({
  companyDiscounts,
  couponsAndOffersQuantity,
  couponsQuantity,
  eventObject,
  hasSelectedStore,
  handleBack,
}) => {
  const ref = useRef<null | HTMLDivElement>(null)

  const storeDataIsValid = useMemo(
    () =>
      companyDiscounts?.company_info &&
      Object.keys(companyDiscounts.company_info).length,
    [companyDiscounts?.company_info]
  )

  const storePath = useMemo(
    () => companyDiscounts?.path,
    [companyDiscounts?.path]
  )

  const hasStorePath = useMemo(() => !!storePath, [storePath])

  const formatedCouponTitle = useMemo(() => {
    if (storeDataIsValid) {
      return makeTitle({
        length: couponsAndOffersQuantity,
        storeName: companyDiscounts?.company_info?.name,
      })
    }
    return ''
  }, [
    storeDataIsValid,
    couponsAndOffersQuantity,
    companyDiscounts?.company_info?.name,
  ])

  useEffect(() => {
    if (couponsAndOffersQuantity) {
      ref.current?.scrollIntoView({ behavior: 'smooth' })
    }
  }, [couponsAndOffersQuantity])

  return (
    <S.Main>
      {hasSelectedStore ? (
        <S.Header>
          <S.BackButton ref={ref} onClick={handleBack}>
            <ArrowBackIosIcon
              fontSize='inherit'
              htmlColor={light.colors.steel}
            />
            <p>Voltar</p>
          </S.BackButton>
        </S.Header>
      ) : null}
      <S.Body>
        <S.Title>{formatedCouponTitle}</S.Title>
        <S.Description>
          Para o cupom ser validado faça a compra na página da loja e cole o
          código no carrinho de compras.
        </S.Description>
        <S.Content>
          {storeDataIsValid && hasStorePath
            ? companyDiscounts?.discount_coupons.map(
                (coupon: Discount, index) => (
                  <CouponCard
                    key={coupon.id}
                    companyInfo={companyDiscounts.company_info}
                    eventObject={{
                      ...eventObject,
                      position: index + 1,
                      totalDiscounts: couponsAndOffersQuantity,
                    }}
                    coupon={coupon}
                    storePath={storePath!}
                  />
                )
              )
            : null}

          {storeDataIsValid && hasStorePath
            ? companyDiscounts?.discount_offers.map(
                (offer: Discount, index) => (
                  <OfferCard
                    companyInfo={companyDiscounts.company_info}
                    eventObject={{
                      ...eventObject,
                      position: couponsQuantity + index + 1,
                      totalDiscounts: couponsAndOffersQuantity,
                    }}
                    key={offer.id}
                    offer={offer}
                    storePath={storePath!}
                  />
                )
              )
            : null}
        </S.Content>
      </S.Body>
    </S.Main>
  )
}

export default HasDiscounts
