import { discountsSummaryService } from 'domain/services/discounts-summary'
import {
  createContext,
  ReactNode,
  useCallback,
  useEffect,
  useState,
} from 'react'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'
import { DiscountsSummaryContextProps } from './state'

export const DiscountsSummaryContext =
  createContext<DiscountsSummaryContextProps>({
    loading: false,
  })

interface DiscountsSummaryProviderProps {
  children: ReactNode
}
const DiscountsSummaryProvider = ({
  children,
}: DiscountsSummaryProviderProps) => {
  const [discountsSummary, setDiscountsSummary] =
    useState<DiscountsSummaryApiResponse[]>()
  const [loading, setLoading] = useState(false)

  const getDiscountsSummary = useCallback(async () => {
    setLoading(true)

    try {
      const discountsSummaryResponse = await discountsSummaryService()

      if (!discountsSummaryResponse) {
        return setLoading(false)
      }

      setLoading(false)
      setDiscountsSummary(discountsSummaryResponse)
    } catch (e) {
      console.error(e)
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    getDiscountsSummary()
  }, [getDiscountsSummary])

  return (
    <DiscountsSummaryContext.Provider value={{ discountsSummary, loading }}>
      {children}
    </DiscountsSummaryContext.Provider>
  )
}

export default DiscountsSummaryProvider
