import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import TextLimit from 'components/TextLimit'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'
import { EventObject } from 'domain/model/event'
import { useCallback } from 'react'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getPhrase } from 'utils/getPhrase'
import { getCurrentUrl } from 'utils/location/get-current-url'
import * as S from './styles'

export interface DiscountsSummaryProps {
  discount: DiscountsSummaryApiResponse
}

interface StoreCouponProps extends DiscountsSummaryProps {
  handleStoreData: () => void
  eventObject: EventObject
  hasBorder?: boolean
  searchTerm?: string
}
const StoreCoupon = ({
  discount,
  searchTerm,
  eventObject,
  hasBorder = false,
  handleStoreData,
}: StoreCouponProps) => {
  const { name, image } = getPhrase(
    discount.company_info.general_reputation.status
  )

  const eventTrigger = useCallback(async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}card_company`,
        eventProps: {
          active_url,
          shortname: discount?.company_info.short_name ?? '',
          company_name: discount?.company_info.name ?? '',
          company_url: discount?.company_info.url ?? '',
          reputation: discount?.company_info?.general_reputation?.status ?? '',
          score:
            discount?.company_info?.general_reputation?.average_score ?? '',
          search_term: searchTerm ?? '',
          total_discounts: discount?.total_discounts ?? 0,
          component: eventObject.componentLocation,
          area: eventObject.areaLocation,
        },
      },
    })
  }, [
    eventObject,
    searchTerm,
    discount?.company_info?.general_reputation?.average_score,
    discount?.company_info?.general_reputation?.status,
    discount?.company_info.short_name,
    discount?.company_info.name,
    discount?.company_info.url,
    discount?.total_discounts,
  ])

  return (
    <S.Main
      hasBorder={hasBorder}
      onClick={() => {
        eventTrigger()
        handleStoreData()
      }}
    >
      {discount?.company_info?.logo_url ? (
        <S.StoreImage width='100%' src={discount.company_info.logo_url} />
      ) : (
        <S.StoreGenericAvatar>
          {discount?.company_info.name.charAt(0)}
        </S.StoreGenericAvatar>
      )}

      <TextLimit>
        <S.StoreName>{discount?.company_info.name}</S.StoreName>
      </TextLimit>

      <S.Reputation>
        <img src={image} alt={name} />
        <p>{name}</p>
      </S.Reputation>

      <S.CouponsCount>
        <S.TotalCoupons>
          {discount.total_discounts > 1
            ? `${discount.total_discounts} cupons`
            : `${discount.total_discounts} cupom`}
        </S.TotalCoupons>
      </S.CouponsCount>
    </S.Main>
  )
}

export default StoreCoupon
