import AlertProvider from 'hooks/AlertProvider/provider'
import DiscountsSummaryProvider from 'hooks/DiscountsSummaryProvider/provider'
import AuthProvider from 'hooks/auth/provider'
import CompanyDiscountsProvider from 'hooks/company-discounts'
import NotificationProvider from 'hooks/notifications/provider'
import { ProfileProvider } from 'hooks/Profile/provider'
import SelectedCompanyDiscountsProvider from 'hooks/selected-company-discounts'
import SelectedCompanyProvider from 'hooks/selected-company/provider'
import { ReactNode } from 'react'
import { Compose } from 'shared/provider-compose'

interface ProviderProps {
  children: ReactNode
}
export function Provider({ children }: ProviderProps) {
  return (
    <Compose
      components={[
        AlertProvider,
        AuthProvider,
        ProfileProvider,
        NotificationProvider,
        CompanyDiscountsProvider,
        DiscountsSummaryProvider,
        SelectedCompanyProvider,
        SelectedCompanyDiscountsProvider,
      ]}
    >
      {children}
    </Compose>
  )
}
