import { SvgIcon } from '@mui/material'
import { ReactNode } from 'react'
import { useTheme } from 'styled-components'
import * as S from './styles'

interface PreferencesLayoutProps {
  titleIcon?: ReactNode
  title: string
  subtitle?: string
  children: ReactNode
}
function PreferencesLayout({
  titleIcon,
  title,
  subtitle,
  children,
}: PreferencesLayoutProps) {
  const theme = useTheme()

  return (
    <S.Main>
      <S.Header color='gray'>
        {titleIcon ? (
          <SvgIcon sx={{ fontSize: '16px' }} htmlColor={theme.colors.steel}>
            {titleIcon}
          </SvgIcon>
        ) : null}
        <S.Title>{title}</S.Title>
      </S.Header>
      {subtitle ? <S.Subtitle>{subtitle}</S.Subtitle> : null}
      <S.List>{children}</S.List>
    </S.Main>
  )
}

export default PreferencesLayout
