import { envVariables } from 'config/env'
import { axiosInterceptableInstance } from 'config/http_client'
import { IToken } from 'hooks/auth/state'

export type NotificationsParamNames = 'preferential_email'
export interface PutExtensionNotificationsConfigProps {
  token?: IToken
  paramName: NotificationsParamNames
  value: number | boolean | string | string[]
}
export async function putExtensionNotificationsConfig({
  token,
  paramName,
  value,
}: PutExtensionNotificationsConfigProps): Promise<any> {
  try {
    if (!token) throw new Error('Invalid token.')

    return await axiosInterceptableInstance({
      method: envVariables.api.account.notificationsConfig.method,
      url: envVariables.api.account.notificationsConfig.path,
      headers: {
        Authorization: `Bearer ${token.access_token}`,
      },
      data: { [paramName]: value },
    })
  } catch (e: any) {
    console.error(`PUT EXTENSION NOTIFICATIONS CONFIG: ${e}`)
    const {
      response: { data, status },
    } = e
    return {
      status,
      message: data?.message
        ? data?.message
        : 'Ocorreu um erro inexperado! Tente novamente mais tarde.',
    }
  }
}
