import CloseIcon from '@mui/icons-material/Close'
import {
  Button,
  Dialog as MuiDialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  TextField,
} from '@mui/material'
import { useTheme } from 'styled-components'
import * as S from './styles'

interface DialogProps {
  list?: any[]
  inputValue: string
  inputLabel: string
  openList?: boolean
  openAdd?: boolean
  canSave: boolean
  dialogTitle: string
  addValue: () => void
  inputValueIsValid?: (value: any) => boolean
  dialogClose: () => void
  setCanSave: (value: boolean) => void
  handleChange?: (type: 'add' | 'remove', value: string) => void
  setInputValue: (value: string) => void
}
export function Dialog({
  list,
  inputValue,
  inputLabel,
  openList = false,
  openAdd = false,
  canSave,
  dialogTitle,
  addValue,
  inputValueIsValid,
  dialogClose,
  setCanSave,
  handleChange,
  setInputValue,
}: DialogProps) {
  const theme = useTheme()

  return (
    <MuiDialog open={openList || openAdd} onClose={dialogClose} sx={S.DialogSx}>
      <DialogContent sx={S.DialogContentSx}>
        <DialogContentText
          sx={
            openList ? S.DialogContentTextListSx : S.DialogContentTextAddSiteSx
          }
        >
          {dialogTitle}
        </DialogContentText>
        {openAdd ? (
          <TextField
            variant='outlined'
            label={inputLabel}
            size='small'
            value={inputValue}
            onChange={(e) => {
              const {
                target: { value },
              } = e

              if (!inputValueIsValid?.(value)) setCanSave(false)
              else setCanSave(true)

              setInputValue(value)
            }}
          />
        ) : null}
        {openList ? (
          <S.SitesList>
            {list?.map((item) => (
              <S.SiteItem key={item}>
                <p>{item}</p>
                <S.IconButton
                  aria-label='remove-site'
                  onClick={() => {
                    handleChange?.('remove', item)
                  }}
                >
                  <CloseIcon fontSize='inherit' />
                </S.IconButton>
              </S.SiteItem>
            ))}
          </S.SitesList>
        ) : null}
      </DialogContent>
      <DialogActions sx={S.DialogActionsSx(openList)}>
        {openAdd ? (
          <Button
            onClick={addValue}
            size='small'
            variant='contained'
            color='primary'
            disabled={!canSave}
            sx={S.SaveButtonSx(openAdd, theme)}
          >
            Salvar
          </Button>
        ) : null}
        <Button
          onClick={dialogClose}
          size='small'
          variant='contained'
          color='primary'
          sx={S.CloseButtonSx(openList, theme)}
        >
          {openAdd ? 'Cancelar' : null}
          {openList ? 'Fechar' : null}
        </Button>
      </DialogActions>
    </MuiDialog>
  )
}
