import DiscountsSummary from 'components/DiscountsSummary'
import { EventObject } from 'domain/model/event'
import { useDiscountsSummary } from 'hooks/DiscountsSummaryProvider/use'
import { useSelectedCompany } from 'hooks/selected-company/use'
import Skeleton from 'react-loading-skeleton'
import { useNavigate } from 'react-router-dom'

export interface NoHasDiscountsProps {
  reputationValid: boolean
  eventObject: EventObject
}

const NoHasDiscounts: React.FC<NoHasDiscountsProps> = ({
  reputationValid,
  eventObject,
}) => {
  const { loading, discountsSummary } = useDiscountsSummary()
  const navigate = useNavigate()
  const { selectCompany } = useSelectedCompany()

  return (
    <>
      {discountsSummary === undefined || loading ? (
        <>
          <Skeleton width='118px' height='140px' />
          <Skeleton width='118px' height='140px' />
          <Skeleton width='118px' height='140px' />
          <Skeleton width='118px' height='140px' />
          <Skeleton width='118px' height='140px' />
          <Skeleton width='118px' height='140px' />
        </>
      ) : (
        discountsSummary &&
        discountsSummary.length > 0 && (
          <DiscountsSummary
            getCompanyData={(store) => {
              selectCompany?.(store)
              navigate('/coupons')
            }}
            reputationValid={reputationValid}
            noCouponsStore={true}
            discountsSummary={discountsSummary}
            eventObject={eventObject}
          />
        )
      )}
    </>
  )
}

export default NoHasDiscounts
