import { mdiClose } from '@mdi/js'
import Icon from '@mdi/react'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { ReactComponent as RALogo } from 'assets/images/reclameaquibranco.svg'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { useCompanyDiscounts } from 'hooks/company-discounts'
import React, { useCallback } from 'react'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import * as TC from 'testComponents'
import { getCurrentUrl } from 'utils/location/get-current-url'
import LoginButton from './components/LoginButton'
import * as S from './styles'
// import Configuration from 'components/Configuration'

const Header: React.FC = () => {
  const { companyDiscounts } = useCompanyDiscounts()

  const eventTrigger = useCallback(async () => {
    const active_url = await getCurrentUrl(EventOrigin.EXTENSION)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}login`,
        eventProps: {
          active_url,
          shortname: companyDiscounts?.company_info.short_name ?? '',
          company_name: companyDiscounts?.company_info.name ?? '',
          reputation:
            companyDiscounts?.company_info.general_reputation?.status ?? '',
          score:
            companyDiscounts?.company_info.general_reputation?.average_score ??
            '',
          ra_verificada:
            companyDiscounts?.company_info.company_flags.is_verified ?? false,
          component: ComponentLocation.MODAL_EXTENSION,
          area: AreaLocation.ENTER,
        },
      },
    })
  }, [
    companyDiscounts?.company_info.general_reputation?.average_score,
    companyDiscounts?.company_info.general_reputation?.status,
    companyDiscounts?.company_info.company_flags.is_verified,
    companyDiscounts?.company_info.name,
    companyDiscounts?.company_info.short_name,
  ])

  return (
    <S.Main>
      <RALogo />

      <S.IconContainer>
        <LoginButton eventTrigger={eventTrigger} />
        {/*  TODO: Engrenagem de opções de silenciar o pin. Verificar mais tarde. */}
        {/* <Configuration/> */}
        <S.CloseButton
          onClick={() => {
            window.close()
          }}
        >
          <Icon path={mdiClose} size='24px' color='#fff' />
        </S.CloseButton>
      </S.IconContainer>

      {process.env.REACT_APP_TEST_MODE === 'true' && (
        <S.TextComponentsMain>
          <TC.ShowStorageContent />
          <TC.ClearAndKeepStoresButton />
          <TC.StorageClearButton />
        </S.TextComponentsMain>
      )}
    </S.Main>
  )
}

export default Header
