import {
  mixpanelIdentifyLogin,
  mixpanelIdentifyLogout,
} from 'adapter/event-adapter/mixpanel-identify'
import { getProfileService } from 'domain/services/profile/get-profile'
import useAuth from 'hooks/auth/use'
import {
  getChromeLocalData,
  removeChromeLocalData,
  setChromeLocalData,
  setChromeSyncData,
} from 'hooks/chrome-storage-change-data'
import { ReactNode, useEffect } from 'react'
import { FETCH_PROFILE_TIME, getTimeWithNow } from 'shared/cache'
import { IS_IDENTIFIED, REMOVE_IDENTIFY } from 'shared/caches/event'
import { isDateExpired } from 'utils/dateHelper'
import { ProfileContext } from './context'
import { CachedProfile, IProfile } from './state'
import { useSyncProfile } from './use'

interface ProfileProviderProps {
  children: ReactNode
}
export function ProfileProvider({ children }: ProfileProviderProps) {
  const { currentData: cachedProfile } = useSyncProfile()
  const { isAuthenticated, token } = useAuth()

  const setProfile = async (data: CachedProfile) => {
    await setChromeSyncData({ profile: data })
  }

  const getProfile = async () => {
    if (!isAuthenticated) return

    if (cachedProfile?.profile && !isDateExpired(cachedProfile?.lastFetch))
      return

    const response = await getProfileService<IProfile>(token?.access_token)

    if (response) {
      await setProfile({
        profile: {
          ...response,
        },
        lastFetch: getTimeWithNow(FETCH_PROFILE_TIME),
      })
    }
  }

  useEffect(() => {
    async function identifyFunc() {
      const isIdentifiedData = await getChromeLocalData(IS_IDENTIFIED)
      const removeIdentifyData = await getChromeLocalData(REMOVE_IDENTIFY)

      const isIdentified = isIdentifiedData?.[IS_IDENTIFIED]
      const removeIdentify = removeIdentifyData?.[REMOVE_IDENTIFY]
      const hasProfile = cachedProfile?.profile.user

      if (removeIdentify) {
        await setChromeLocalData({
          [REMOVE_IDENTIFY]: false,
        })
        await removeChromeLocalData('clientId')
        return mixpanelIdentifyLogout()
      }
      if (!isIdentified && hasProfile) {
        await setChromeLocalData({
          [IS_IDENTIFIED]: true,
          clientId: cachedProfile?.profile.user.userId,
        })
        mixpanelIdentifyLogin(cachedProfile?.profile.user.userId)
      }
    }
    identifyFunc()
  }, [cachedProfile])

  useEffect(() => {
    if (token) getProfile()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token])

  return (
    <ProfileContext.Provider
      value={{
        cachedProfile,
        setProfile,
      }}
    >
      {children}
    </ProfileContext.Provider>
  )
}
