import { UrlService } from './urlService';

interface CompleteUrlData {
  prefix: string;
  value: string;
}
export class CompleteUrl {
  private urlService: UrlService;

  private prefix: string;

  private value: string;

  constructor({ prefix, value }: CompleteUrlData, urlService: UrlService) {
    this.urlService = urlService;
    this.prefix = prefix;
    this.value = value;
  }

  get() {
    this.urlService.setParamValue({
      prefix: this.prefix,
      value: this.value,
    });

    return this.urlService.getUrl();
  }
}
