import { Affiliate, affiliateList } from 'shared/affiliates';

import { CompleteUrl } from '../completeUrl';
import { UrlService } from '../urlService';
import { AffiliatePrefix } from './affiliatePrefix';

interface AffiliateParamServiceParams {
  url: string;
  affiliateId: number;
  value: string;
}
export class AffiliateParamService {
  private url: string;

  private affiliateId: number;

  private value: string;

  private affiliates: Affiliate[];

  constructor({ url, affiliateId, value }: AffiliateParamServiceParams) {
    this.url = url;
    this.affiliateId = affiliateId;
    this.affiliates = affiliateList;
    this.value = value;
  }

  get() {
    const affiliatePrefix = new AffiliatePrefix({
      affiliates: this.affiliates,
      affiliateId: this.affiliateId,
    });

    const prefix = affiliatePrefix.get();

    if (!prefix) return this.url;

    const urlService = new UrlService(this.url);
    const completeUrl = new CompleteUrl(
      {
        prefix,
        value: this.value,
      },
      urlService,
    );

    return completeUrl.get();
  }
}
