import StoreCoupon from 'components/StoreCoupon'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'
import { EventObject } from 'domain/model/event'
import * as S from './styles'

interface DiscountsSummaryProps {
  discountsSummary: DiscountsSummaryApiResponse[]
  getCompanyData?: (data: DiscountsSummaryApiResponse) => void
  noCouponsStore?: boolean
  reputationValid: boolean
  eventObject: EventObject
}
const DiscountsSummary = ({
  discountsSummary,
  getCompanyData,
  noCouponsStore,
  reputationValid,
  eventObject,
}: DiscountsSummaryProps) => {
  const handleTitle = () => {
    if (!reputationValid) {
      return 'Que tal conhecer lojas confiáveis?'
    }

    if (noCouponsStore) {
      return 'Essa loja não possui cupons disponíveis :('
    }

    return 'Os melhores e mais confiáveis cupons de desconto'
  }

  return (
    <S.Main>
      <S.CouponsTitle reputationValid={!reputationValid}>
        {handleTitle()}
      </S.CouponsTitle>
      {noCouponsStore && reputationValid && (
        <S.SubTitle>
          Conheça outras lojas que possuem cupons disponíveis
        </S.SubTitle>
      )}
      <S.StoreCouponsCardsContainer>
        {discountsSummary.map((discount) => (
          <StoreCoupon
            key={discount.company_info.id}
            discount={discount}
            hasBorder={true}
            eventObject={eventObject}
            handleStoreData={() => {
              getCompanyData?.(discount)
            }}
          />
        ))}
      </S.StoreCouponsCardsContainer>
    </S.Main>
  )
}

export default DiscountsSummary
