import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import {
  removeChromeLocalData,
  setChromeLocalData,
} from 'hooks/chrome-storage-change-data'
import { useSelectedCompany } from 'hooks/selected-company/use'
import {
  ReactNode,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react'
import { SELECTED_COMPANY_DISCOUNTS } from 'shared/caches/company-discounts'
import { getItemFromCache } from 'utils/cacheUtils'
import { selectedCompanyDiscountsController } from './controllers/selected-company-controller'
import { companyDiscountsController } from './controllers/company-discounts-controller'

interface GetCompanyDiscountsProps {
  shortname: string
  path: string
  ra_path: string
}

interface SelectedCompanyDiscountsContextProps {
  loading: boolean
  companyDiscounts?: DiscountsApiResponseWithPath
  couponsQuantity: number
  offersQuantity: number
  couponsAndOffersQuantity: number
  getCompanyDiscounts?: (props: GetCompanyDiscountsProps) => void
  hasCoupons?: () => boolean
  hasOffers?: () => boolean
  clearSelectedCompanyDiscounts?: () => void
}
const SelectedCompanyDiscountsContext =
  createContext<SelectedCompanyDiscountsContextProps>({
    loading: false,
    couponsQuantity: 0,
    offersQuantity: 0,
    couponsAndOffersQuantity: 0,
  })

export const useSelectedCompanyDiscounts = () =>
  useContext(SelectedCompanyDiscountsContext)

interface SelectedCompanyDiscountsProviderProps {
  children: ReactNode
}
function SelectedCompanyDiscountsProvider({
  children,
}: SelectedCompanyDiscountsProviderProps) {
  const { selectedCompany } = useSelectedCompany()
  const [companyDiscounts, setCompanyDiscounts] =
    useState<DiscountsApiResponseWithPath>()
  const [loading, setLoading] = useState(false)

  async function getCompanyDiscounts({
    shortname,
    path,
    ra_path,
  }: GetCompanyDiscountsProps) {
    if (shortname) {
      setLoading(true)
      const selectedCompanyController = selectedCompanyDiscountsController()
      try {
        const cachedData = await selectedCompanyController.getCachedData()

        if (
          selectedCompanyController.hasCache({
            cachedData,
            selectedCompanyShortname: shortname,
          })
        ) {
          setLoading(false)
          return setCompanyDiscounts(cachedData)
        }

        const companyController = companyDiscountsController()

        const chromeCachedData =
          await companyController.getCachedCompanyDiscountsData(shortname)

        if (companyController.notHaveCache(chromeCachedData)) {
          const companyDiscountsApiResponse =
            await companyController.getDiscountsData(shortname)

          if (
            companyController.companyDiscountsIsInvalid(
              companyDiscountsApiResponse
            )
          )
            throw new Error('Invalid Discounts API Response')

          const dataWithPath: DiscountsApiResponseWithPath = {
            ...companyDiscountsApiResponse,
            path,
            ra_path,
          }

          await setChromeLocalData({
            [SELECTED_COMPANY_DISCOUNTS]: dataWithPath,
          })
          setCompanyDiscounts(dataWithPath)

          return setLoading(false)
        }

        await setChromeLocalData({
          [SELECTED_COMPANY_DISCOUNTS]: chromeCachedData.data?.data,
        })
        setCompanyDiscounts(chromeCachedData?.data?.data)
      } catch (e) {
        console.error(JSON.stringify(e))
        return setLoading(false)
      }

      setLoading(false)
    }
  }

  useEffect(() => {
    if (
      selectedCompany?.company_info?.short_name &&
      selectedCompany?.company_info?.url
    )
      getCompanyDiscounts({
        shortname: selectedCompany.company_info.short_name,
        path: selectedCompany.company_info.url,
        ra_path: selectedCompany.company_info.ra_company_url,
      })
  }, [selectedCompany])

  const hasCoupons = useCallback(() => {
    return !!companyDiscounts?.discount_coupons.length
  }, [companyDiscounts?.discount_coupons.length])

  const hasOffers = useCallback(() => {
    return !!companyDiscounts?.discount_offers.length
  }, [companyDiscounts?.discount_offers.length])

  const clearSelectedCompanyDiscounts = async () => {
    await removeChromeLocalData(SELECTED_COMPANY_DISCOUNTS)
    setCompanyDiscounts(undefined)
  }

  const couponsQuantity = useMemo(
    () => companyDiscounts?.discount_coupons.length ?? 0,
    [companyDiscounts]
  )
  const offersQuantity = useMemo(
    () => companyDiscounts?.discount_offers.length ?? 0,
    [companyDiscounts]
  )

  useEffect(() => {
    async function getData() {
      const cachedData = await getItemFromCache<DiscountsApiResponseWithPath>(
        SELECTED_COMPANY_DISCOUNTS
      )

      if (cachedData) {
        return setCompanyDiscounts(cachedData)
      }
    }
    getData()
  }, [])

  return (
    <SelectedCompanyDiscountsContext.Provider
      value={{
        loading,
        companyDiscounts,
        couponsQuantity,
        offersQuantity,
        couponsAndOffersQuantity: couponsQuantity + offersQuantity,
        hasOffers,
        hasCoupons,
        getCompanyDiscounts,
        clearSelectedCompanyDiscounts,
      }}
    >
      {children}
    </SelectedCompanyDiscountsContext.Provider>
  )
}

export default SelectedCompanyDiscountsProvider
