import {
  AccountCircleOutlined,
  HomeOutlined,
  SearchOutlined,
} from '@mui/icons-material'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { NotificationIcon } from 'components/Header/NotificationIcon'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import { useCompanyDiscounts } from 'hooks/company-discounts'
import useNotifications from 'hooks/notifications/use'
import { useProfile } from 'hooks/Profile/use'
import React, { useCallback, useEffect, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import { IconContainer as IconNavLink, Nav, WrapperContainer } from './styles'

const Footer: React.FC = () => {
  const location = useLocation()
  const { cachedProfile } = useProfile()
  const { companyDiscounts } = useCompanyDiscounts()
  const [showStatusReq, setShowStatusReq] = useState(true)
  const { notifications } = useNotifications()
  const { setFirstLogin } = useAuth()

  const handleNotification = useCallback(() => {
    const notificationConfig = cachedProfile?.profile?.extension_config?.find(
      (config) => config.extension_id === '61ae7936dbf23f70d0e64d54'
    )

    if (notificationConfig) setShowStatusReq(notificationConfig.isChecked)
  }, [cachedProfile])

  useEffect(() => {
    handleNotification()
  }, [handleNotification])

  const eventTrigger = useCallback(
    async (area: string) => {
      const active_url = await getCurrentUrl(EventOrigin.EXTENSION)

      const areaList: { [key: string]: AreaLocation } = {
        home: AreaLocation.HOME,
        coupons: AreaLocation.SEARCH,
        notifications: AreaLocation.NOTIFICATION,
        users: AreaLocation.PREFERENCES,
      }

      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}navbar`,
          eventProps: {
            active_url,
            shortname: companyDiscounts?.company_info.short_name ?? '',
            company_name: companyDiscounts?.company_info.name ?? '',
            reputation:
              companyDiscounts?.company_info.general_reputation?.status ?? '',
            score:
              companyDiscounts?.company_info.general_reputation
                ?.average_score ?? '',
            ra_verificada:
              companyDiscounts?.company_info.company_flags.is_verified ?? false,
            component: ComponentLocation.MODAL_EXTENSION,
            area: areaList[area],
          },
        },
      })
    },
    [
      companyDiscounts?.company_info.general_reputation?.average_score,
      companyDiscounts?.company_info.general_reputation?.status,
      companyDiscounts?.company_info.company_flags.is_verified,
      companyDiscounts?.company_info.name,
      companyDiscounts?.company_info.short_name,
    ]
  )

  return (
    <Nav id='navigation'>
      <WrapperContainer>
        <IconNavLink
          onClick={() => {
            eventTrigger('home')
            setFirstLogin(false)
          }}
          to='/home'
        >
          <HomeOutlined
            sx={{
              fill: `${location.pathname === '/home' ? '#02793E' : '#4B5963'}`,
            }}
          />
        </IconNavLink>

        <IconNavLink
          onClick={() => {
            eventTrigger('coupons')
            setFirstLogin(false)
          }}
          to='/coupons'
        >
          <SearchOutlined
            sx={{
              fill: `${
                location.pathname === '/coupons' ? '#02793E' : '#4B5963'
              }`,
            }}
          />
        </IconNavLink>

        <IconNavLink
          to='/notifications'
          onClick={() => {
            eventTrigger('notifications')
            setFirstLogin(false)
          }}
        >
          <NotificationIcon
            fill={
              location.pathname === '/notifications' ? '#02793E' : '#4B5963'
            }
            hasNotifications={notifications?.length > 0 && showStatusReq}
          />
        </IconNavLink>

        <IconNavLink
          onClick={() => {
            eventTrigger('users')
          }}
          to='/users'
        >
          <AccountCircleOutlined
            sx={{
              fill: `${location.pathname === '/users' ? '#02793E' : '#4B5963'}`,
            }}
          />
        </IconNavLink>
      </WrapperContainer>
    </Nav>
  )
}

export default Footer
